      lines.push(
        `alcantara_radio_next_announcements_total{result="${result}"} ${this.nextAnnouncements.get(result) ?? 0}`,
      );
    }
    lines.push(
      '# HELP alcantara_radio_handoffs_total Song-to-song handoffs at an accepted end, by bounded path.',
