  it('keeps the song active and exposes a bounded degraded state when an intro fails', async () => {
    const { engine, radioService, flightService, prisma } = createEngine({
      reconciled: true,
      radio: true,
    });
    prisma.songIntro.findUnique.mockResolvedValue({
      programId: 'radio-1',
